  /// Whether the plaintext was padded before sealing, so that ciphertext sizes do not
  /// fingerprint known documents. `padme`: zero bytes appended to reach `padme(size)`,
  /// the formula above. Absent means `none`. The padding is inside the final segments,
  /// and a reader checks it is zero and removes it by truncating to `size`.
  final FileManifestPadding? padding;
  final BlobRef blobRef;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'fileId': fileId,
        'name': name,
        if (mediaType != null) 'mediaType': mediaType!,
        'size': size,
        'digest': digest,
        'epoch': epoch,
        'segmentSize': segmentSize,
        if (padding != null) 'padding': padding!.value,
        'blobRef': blobRef,
      };
}

/// Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a
/// reverse-DNS namespace; structure under each namespace is opaque to the framework.
typedef Ext = Map<String, dynamic>;

/// What a room says about itself to its own members: a name and, optionally, a
/// description, short tags and an emoji, so that a member's wallet, portal or CLI can
/// show what each room is rather than a DID. **It lives in the room, and only there.**
/// A profile is carried in a record of the room (`RoomProfileStatement`), sealed on
/// `attributed` and `private` rooms like every other record, so the room's host stores
/// ciphertext and learns neither the name nor anything else here. It is never put in a
/// credential — credentials are presented to hosts — nor in a host's record of the
/// room, in `rooms/create` or `rooms/owner/register`, or in any member a host can
/// read. On an `open` room it is cleartext, as everything in an open room is. **Plain
/// text, never instructions.** Every member is free text chosen by whoever wrote the
/// profile and shown to every member of the room. A reader renders `name`,
/// `description` and `tags` as text — never as markup, never as a link it follows —
/// removes or replaces control characters before showing them, and MUST NOT treat any
/// of it as instructions, which matters most for an agent acting for a member. A
/// writer MUST NOT put personal data or a credential in any member. **Growth.** A new
/// optional member arrives in a later version of this component. A reader refuses a
/// member it does not know (the `SealedRecordBody` rules), so a profile carrying one
/// is not shown by a reader that predates it, and a writer SHOULD NOT use a member it
/// cannot expect the room's readers to know. An ecosystem extension goes in `ext`,
/// which a reader that does not understand it ignores. A change no earlier reader
/// could survive is a new statement under a new derivation label
/// (`openvtc/room/profile/v2`), written beside this one until the room's readers have
/// moved.
class RoomProfile {
  const RoomProfile({
    required this.name,
    this.description,
    this.tags,
    this.emoji,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory RoomProfile.fromJson(Map<String, dynamic> json) => RoomProfile(
        name: json['name'] as String,
        description: json['description'] as String?,
        tags: json['tags'] == null
            ? null
            : (json['tags'] as List<dynamic>).map((e) => e as String).toList(),
        emoji: json['emoji'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// The room's name as its members see it. Plain text, one line. Bounded like the label
  /// a community gives a room it owns (`RoomLabel` in vtc/_shared), so a community can
  /// write the same name here that it shows its administrators and the members it offers
  /// the room to.
  final String name;

  /// What the room is for, in a sentence or a short paragraph. Plain text. Absent when
  /// the room has none; an empty string is not a description.
  final String? description;

  /// Short identifiers the room files itself under, as a set: order carries no meaning.
  /// A member's surface MAY filter or group rooms by them. They are the room's own and
  /// shown to its members — distinct from the tags a community files the rooms it owns
  /// under for its administrators, which are never written here.
  final List<String>? tags;

  /// One emoji — a single extended grapheme cluster, such as `📋` — that a surface MAY
  /// show beside the name. Text, rendered as text: never an image, never a URL, never
  /// anything a reader fetches, since a fetched icon would tell whoever serves it which
  /// member opened which room, and when. A reader that cannot render it shows nothing in
  /// its place.
  final String? emoji;

  /// Ecosystem-defined extension members per SPEC.md §4.5.1. A reader ignores what it
  /// does not understand.
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'name': name,
        if (description != null) 'description': description!,
        if (tags != null) 'tags': tags!,
        if (emoji != null) 'emoji': emoji!,
        if (ext != null) 'ext': ext!,
      };
}

/// The room's profile as a record carries it: the `roomProfile` member of a
/// `SealedRecordBody`, signed by its author like every record body, with the evidence
/// a reader needs to decide whether the author was entitled to say it. **Where it is:
/// one record per epoch, at a key only members can compute.** On an `attributed` or
/// `private` room the profile written under epoch `E` is stored at the record key
/// profile_key(E) = base64url-nopad(HKDF-SHA256(ikm = storage_key(E), salt = "", info
/// = "openvtc/room/profile/v1" || roomId || u64be(E), L = 16)) where `storage_key(E)`
/// is the room's storage key for epoch `E` — the one records sealed under `E` are
/// sealed with, as for a file key (`blobs.schema.json`) — `roomId` is its UTF-8 bytes
/// exactly as on the wire, `u64be` is as `blobs.schema.json` defines it, and `salt` is
/// the empty string. The result is 22 characters, the shape of any random record key,
/// so to the host it is one more opaque record and the family's rule that a sealed
/// room's keys are opaque (`RecordMetadata.key`) holds for it as for any other. A
/// member finds it knowing nothing but the room and the epoch, which is all a member
/// who has just joined has. Since `storage_key(E)` never leaves a member's key holder,
/// it is the key holder that computes it (`rooms/keys/profile/read`,
/// `rooms/keys/profile/write`). On an `open` room, which has no storage key and hides
/// nothing from its host, the profile is the record at the fixed key `room-profile`,
/// and its `cleartext.body` is the UTF-8 JSON of the signed `SealedRecordBody` — the
/// object the sealed tiers seal — so that a reader verifies one thing on every tier. A
/// writer SHOULD also set `cleartext.title` to the profile's `name`. The record is
/// written with `rooms/records/put` like any other, so a host enforces only `write` on
/// it and cannot tell it from any other record. Whether its author could say what the
/// room is called is therefore decided by readers, from what the statement carries.
/// **Who may write it.** The author's `authority` must confer `curate` or `admin` at
/// the room's scope: `admin` because naming the room is part of governing it, `curate`
/// because it is the standing to judge what the room's shared knowledge is, and a
/// room's name and purpose are the first thing a member reads of it. `write` alone
/// never suffices: every member able to add a record could otherwise rename the room
/// for everyone. **Accepting one.** A reader resolving a room's profile MUST apply to
/// the record at the profile's location the `SealedRecordBody` reading rules (1)–(4) —
/// on an `open` room to the body parsed from `cleartext.body`, with rule (4) against
/// the author the host recorded — and MUST also refuse it unless: 1. it carries
/// `roomProfile` and none of `title`, `description`, `body`, `tags` and `file`; 2. on
/// a sealed tier, the epoch it was sealed under is `E`, the epoch whose key located
/// it; 3. `authority` verifies as a host verifies a chain (`AuthorityPresentation`):
/// at most 8 links, leaf first; every link's `proof` made with a key its own `issuer`
/// lists for `assertionMethod`; the last link issued by `roomId`; no link widening
/// what its parent conferred, in actions, scope or validity; the whole conferring
/// `curate` or `admin` at this room's scope; the leaf's subject equal to the body's
/// `author`, which stands in for a host's presenter binding; and every link valid at
/// `issuedAt` rather than at the moment of reading. The reader MUST NOT dereference a
/// link it was not given; 4. `issuedAt` is no later than five minutes after, and no
/// earlier than one hour before, the `updatedAt` the host reports for the record; 5.
/// where the reader holds a `RevocationList` for the room, verified as a host verifies
/// one, no link of `authority` is revoked by an entry whose `revokedAt` is at or
/// before `issuedAt`. A reader MUST ignore a profile that fails any of these, as
/// though it were absent — and, unlike an ordinary record, SHOULD say that it did,
/// naming the author where the tier discloses one: a profile written by somebody
/// without the standing to write it is somebody trying to rename the room.
/// **Revocation is not retroactive.** A profile written while its author held the
/// standing to write it stays valid after that author is removed, their grant lapses,
/// or a `room` entry resets every credential. The statement was made with authority;
/// withdrawing the authority withdraws what the author may do next, not what they
/// already did, and the alternative — every member's view of the room's name going
/// blank when whoever named it is removed — is something nobody asked for. It is not a
/// back door. A removed party cannot write afterwards, because a host refuses every
/// presentation a list it holds revokes; a statement back-dated into a grant its
/// author no longer holds fails item 4 unless the host colludes; and removal advances
/// the room's epoch, after which the owner's key holder re-writes the profile under
/// the new epoch as the owner (`rooms/keys/profile/write`), so on the ordinary path
/// the removed author's statement is superseded by the same act that removes them.
/// **Choosing among several.** There is at most one profile per epoch, because there
/// is one record per key. A reader at epoch `C` takes the profile at `profile_key(C)`;
/// if there is none, or it fails the checks above, it tries `C - 1`, and so on down to
/// the earliest epoch it can derive a storage key for, and takes the first one it
/// accepts — the newest. It MUST NOT prefer an older profile to a newer one it
/// accepts. A record at a profile location that is `retracted` is a profile
/// deliberately cleared — retraction is `rooms/records/curate`, for which a host
/// requires `curate` — and the walk stops there: the room has no profile. A profile
/// accepted below `C` is **stale**: written before the room's latest epoch advance and
/// not re-written since. A member of a `fromJoin` room cannot walk back at all, which
/// is why the profile is re-written at every advance. **Size.** A writer SHOULD set
/// `padding` so that the UTF-8 JSON of the signed body is a multiple of 1024 bytes, so
/// that a host comparing ciphertext lengths learns nothing about how long the name or
/// the description is. A reader ignores `padding`.
class RoomProfileStatement {
  const RoomProfileStatement({
    required this.profile,
    required this.issuedAt,
    required this.authority,
    this.padding,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory RoomProfileStatement.fromJson(Map<String, dynamic> json) =>
      RoomProfileStatement(
        profile: RoomProfile.fromJson(json['profile'] as Map<String, dynamic>),
        issuedAt: json['issuedAt'] as String,
        authority: (json['authority'] as List<dynamic>)
            .map((e) => e as String)
            .toList(),
        padding: json['padding'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  final RoomProfile profile;

  /// When the author made this statement: signed with it, the instant `authority` is
  /// evaluated at, and bounded against the host's `updatedAt` for the record so that it
  /// cannot be back-dated into a grant the author no longer holds.
  final String issuedAt;

  /// The author's authority chain, LEAF FIRST, ending with a credential the room issued,
  /// conferring `curate` or `admin` on `author` at this room's scope. The credentials
  /// themselves, never a zero-knowledge presentation: a reader is a member, who already
  /// sees `author`. Carried in the statement because readers, not the host, decide
  /// whether its author could say it, and a reader fetches no link it was not given.
  /// Capped at 8, as a presentation is.
  final List<String> authority;

  /// Ignored by readers; see **Size**. A writer SHOULD use spaces.
  final String? padding;

  /// Ecosystem-defined extension members per SPEC.md §4.5.1.
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'profile': profile.toJson(),
        'issuedAt': issuedAt,
        'authority': authority,
        if (padding != null) 'padding': padding!,
        if (ext != null) 'ext': ext!,
      };
}

/// The plaintext inside `SealedRecord.ciphertext` on an `attributed` or `private`
/// room, as JSON, signed by its author. Client to client: no host task carries it,
/// because a host receives only ciphertext. Defined so that every member's client
/// writes and reads the same thing. **Producing.** A writer builds the object without
/// `proof`, signs it with a W3C Data Integrity proof whose `verificationMethod` is a
/// key of `author` and whose `proofPurpose` is `assertionMethod`, and seals the result
/// (its UTF-8 JSON bytes) under the AEAD that binds the same `roomId`, `key`,
/// `version` and epoch. A writer MUST support `eddsa-jcs-2022`; `ecdsa-jcs-2019` MAY
/// be used for a hardware-backed signer. **Reading.** After opening a record a reader
/// MUST, before showing any member of it or trusting its `file`: (1) parse it as this
/// object and refuse an unknown member; (2) verify `proof` against `author`'s DID
/// document, for `assertionMethod`; (3) check that `roomId`, `key` and `version` equal
/// the location the record was sealed at — the record's `roomId` and `key`, and
/// `sealed.version` where present, else the record's `version` (`SealedRecord`); (4)
/// on an `attributed` room, check that `author` equals the `author` the host recorded
/// for the record. A reader MUST refuse a record that fails any of these, and MUST NOT
/// show it with a warning instead. **A record curated before `sealed.version`
/// existed.** A host that predates `SealedRecord.version` moved such a record's
/// version without recording the one it was sealed at, so it opens at neither. Where a
/// record carries no `sealed.version` and does not open at its own `version`, a reader
/// MAY try each earlier version in turn, newest first, and use the first at which it
/// opens; rule (3) then checks the body against that version. It MUST NOT try a
/// version greater than the record's own. The AEAD makes a wrong guess fail rather
/// than mislead, and the author's signature over the location makes the version that
/// opened the one the author wrote — so the search recovers the record without
/// trusting the host for the answer. **Why the location is signed as well as sealed.**
/// The AEAD stops the host relocating ciphertext, but every member can open and
/// re-seal a record. Without `roomId`, `key` and `version` under the author's
/// signature, a member could copy another member's signed body to a new key or a later
/// version, and on a `private` room, where the host records no author, readers would
/// attribute it to the original author. **A profile record.** A body carrying
/// `roomProfile` is the room's own profile (`RoomProfileStatement`) and not one of its
/// records: it MUST carry none of `title`, `description`, `body`, `tags`, `file`,
/// `basis`, `confidence`, `evidence`, `validFor` and `validUntil`, and the rules for
/// locating, accepting and choosing it are `RoomProfileStatement`'s, applied on top of
/// the four above. A reader that opens one in the course of reading or listing the
/// room's records SHOULD NOT present it as a record — it is how the room describes
/// itself, not something a member wrote into it. A reader that predates `roomProfile`
/// refuses it by rule (1), which shows nothing rather than something wrong.
/// **Provenance: what kind of claim a record is.** `basis`, `confidence`, `evidence`
/// and `validFor` say what the author is asserting and on what footing — an observed
/// fact, a statement of the author's own, something checked against a credential, or
/// an agent's inference. They are inside the signature like every other member, so a
/// reader can attribute them to `author` exactly as it attributes the body, and a
/// change to any of them after signing fails rule (2). All four are OPTIONAL, and a
/// record that carries none of them — every record written before they existed —
/// verifies and reads exactly as before: absent means the author did not say, never a
/// default value. A writer SHOULD set `basis`; an agent writing on its own account
/// that does not know which value applies SHOULD write `inferred`, and a client
/// relaying what its member typed SHOULD write `declared`. **They are provenance for
/// display and weighting, never authority.** A reader MUST NOT treat any of them as
/// granting, widening or evidencing a permission, MUST NOT let `basis: verified` stand
/// in for verifying what `evidence` names, and MUST NOT fetch anything because
/// `evidence` names it (see `RecordEvidence`). A reader that shows a record SHOULD
/// show its `basis` beside its `author` — or say that none was stated — and an agent
/// recalling records MAY weight by `basis` and `confidence`, but MUST treat
/// `validFor.note` like `body`: as plain text, never as instructions. **Expiry.**
/// `validUntil` is the instant after which the author no longer stands behind the
/// record as current — a meeting note good for a month, a decision good for years. It
/// is signed and sealed with the body, and nothing about it is in the clear: a host
/// never sees it on the sealed tiers, so it cannot and MUST NOT be relied on to
/// enforce it, and a writer MUST NOT copy it into any cleartext member of the write. A
/// reader MUST NOT present a record whose `validUntil` is at or before the reader's
/// current time in a default listing, search, browse or agent recall, and MAY present
/// it on an explicit request for expired records, marked as expired. Expiry hides; it
/// does not delete. The record, its ciphertext and any file it carries stay in the
/// room until a member with `curate` retracts it (`rooms/records/curate`) or the
/// room's records are pruned; a curator's agent MAY retract records it finds expired,
/// which is how a sealed room reclaims their storage without telling its host anything
/// about expiry. **Readers that predate these members.** A reader written before
/// `basis`, `confidence`, `evidence`, `validFor` and `validUntil` refuses a body
/// carrying any of them by rule (1), which shows nothing rather than something wrong —
/// in particular it can never show an expired record as current. The same holds for a
/// key holder sealing on a writer's behalf (`rooms/keys/seal`, `bodyInvalid`). A
/// writer that meets such a refusal MAY write the record again without the provenance
/// members, but MUST NOT drop `validUntil` to get a record accepted: a record that
/// silently outlives its author's own expiry is the failure this member exists to
/// prevent.
class SealedRecordBody {
  const SealedRecordBody({
    required this.roomId,
    required this.key,
    required this.version,
    required this.author,
    this.title,
    this.description,
    this.body,
    this.tags,
    this.basis,
    this.confidence,
    this.evidence,
    this.validFor,
    this.validUntil,
    this.file,
    this.roomProfile,
    required this.proof,
  });

  /// Read this payload from a decoded JSON object.
  factory SealedRecordBody.fromJson(Map<String, dynamic> json) =>
      SealedRecordBody(
        roomId: json['roomId'] as String,
        key: json['key'] as String,
        version: json['version'] as int,
        author: json['author'] as String,
        title: json['title'] as String?,
        description: json['description'] as String?,
        body: json['body'] as String?,
        tags: json['tags'] == null
            ? null
            : (json['tags'] as List<dynamic>).map((e) => e as String).toList(),
        basis:
            json['basis'] == null ? null : RecordBasis(json['basis'] as String),
        confidence: json['confidence'] == null
            ? null
            : (json['confidence'] as num).toDouble(),
        evidence: json['evidence'] == null
            ? null
            : (json['evidence'] as List<dynamic>).map((e) => e).toList(),
        validFor: json['validFor'] == null
            ? null
            : PermittedUse.fromJson(json['validFor'] as Map<String, dynamic>),
        validUntil: json['validUntil'] as String?,
        file: json['file'] == null
            ? null
            : FileManifest.fromJson(json['file'] as Map<String, dynamic>),
        roomProfile: json['roomProfile'] == null
            ? null
            : RoomProfileStatement.fromJson(
                json['roomProfile'] as Map<String, dynamic>),
        proof: json['proof'] as Map<String, dynamic>,
      );

  /// The room the record was written in, exactly as on the wire.
  final String roomId;

  /// The record's key, as in `rooms/records/put`.
  final String key;

  /// The version the writer intended the record to take, as sealed with
  /// `rooms/keys/seal`: the version the body is bound to. A record curated since keeps
  /// its body and moves to a new version, and carries this one as `sealed.version`
  /// (`SealedRecord`).
  final int version;

  /// The DID of the party that wrote the record: the member, or the agent acting under
  /// an attenuated credential, whose key signed `proof`. On a `private` room this is the
  /// only attribution there is.
  final String author;
  final String? title;
  final String? description;

  /// The record's text, markdown. Human-readable, never a model-optimised blob, and
  /// rendered inert.
  final String? body;
  final List<String>? tags;
  final RecordBasis? basis;
  final RecordConfidence? confidence;
  final RecordEvidenceList? evidence;
  final PermittedUse? validFor;
  final RecordValidUntil? validUntil;

  /// Present when the record carries a file. Its `blobRef` MUST be the one the record
  /// names in `blobs`.
  final FileManifest? file;

  /// Present only on the room's profile record, which then carries no `title`,
  /// `description`, `body`, `tags` or `file`. See `RoomProfileStatement`.
  final RoomProfileStatement? roomProfile;

  /// The author's Data Integrity proof over every other member.
  final Map<String, dynamic> proof;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'roomId': roomId,
        'key': key,
        'version': version,
        'author': author,
        if (title != null) 'title': title!,
        if (description != null) 'description': description!,
        if (body != null) 'body': body!,
        if (tags != null) 'tags': tags!,
        if (basis != null) 'basis': basis!.value,
        if (confidence != null) 'confidence': confidence!,
        if (evidence != null) 'evidence': evidence!,
        if (validFor != null) 'validFor': validFor!.toJson(),
        if (validUntil != null) 'validUntil': validUntil!,
        if (file != null) 'file': file!.toJson(),
        if (roomProfile != null) 'roomProfile': roomProfile!.toJson(),
        'proof': proof,
      };
}

/// One rung of a room's epoch key chain: the storage key of epoch `epoch - 1`, sealed
/// under the storage key of `epoch`. A group key schedule offers no way to derive an
/// earlier epoch's key from a later one — that property is what makes removing a
/// member mean something — so without a chain the first membership change makes every
/// record already in the room unopenable by everyone, including whoever wrote it. The
/// chain is the one-way street run deliberately the other way: a member holding the
/// current key walks it backwards to any retained epoch, and a member holding an
/// earlier key still derives nothing later. Removal stays forward-only; reading stays
/// possible. What a chain costs is stated where it is chosen, in the room's retention
/// policy.
class EpochLink {
  const EpochLink({
    required this.epoch,
    required this.wrapped,
    required this.nonce,
  });

  /// Read this payload from a decoded JSON object.
  factory EpochLink.fromJson(Map<String, dynamic> json) => EpochLink(
        epoch: json['epoch'] as int,
        wrapped: json['wrapped'] as String,
        nonce: json['nonce'] as String,
      );

  /// The epoch whose storage key opens this link; it wraps the storage key of `epoch -
  /// 1`. Never 1: a room's first epoch has no predecessor, so a link claiming one wraps
  /// something that is not an earlier epoch's key.
  final int epoch;

  /// The wrapped predecessor key, base64url. Bound by AEAD associated data to `roomId`
  /// and to this link's own position in the chain, so a link lifted to another rung, or
  /// served under another room, fails to open rather than yielding a key that is wrong.
  /// The binding is load-bearing rather than decorative: every rung is a fixed-length
  /// key sealed under a fixed-length key, so nothing about the ciphertext itself says
  /// where it belongs.
  final String wrapped;

  /// AEAD nonce, base64url.
  final String nonce;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'epoch': epoch,
        'wrapped': wrapped,
        'nonce': nonce,
      };
}

/// Curation state. `retracted` is a tombstone: the body is gone, the key and version
/// remain so incremental sync converges and the audit chain stays intact.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const RecordMetadataStatus(String value) {
  static const RecordMetadataStatus active = RecordMetadataStatus('active');
  static const RecordMetadataStatus deprecated =
      RecordMetadataStatus('deprecated');
  static const RecordMetadataStatus retracted =
      RecordMetadataStatus('retracted');

  /// Every value this specification's schema permits.
  static const List<RecordMetadataStatus> values = <RecordMetadataStatus>[
    active,
    deprecated,
    retracted
  ];
}

/// What `rooms/records/list` returns. Never the body: ranking happens on the client,
/// and a host that returned every body would make the caller pay for the whole room on
/// every listing.
class RecordMetadata {
  const RecordMetadata({
    required this.key,
    required this.version,
    this.epoch,
    this.status,
    required this.updatedAt,
    this.title,
    this.description,
    this.author,
  });

  /// Read this payload from a decoded JSON object.
  factory RecordMetadata.fromJson(Map<String, dynamic> json) => RecordMetadata(
        key: json['key'] as String,
        version: json['version'] as int,
        epoch: json['epoch'] as int?,
        status: json['status'] == null
            ? null
            : RecordMetadataStatus(json['status'] as String),
        updatedAt: json['updatedAt'] as String,
        title: json['title'] as String?,
        description: json['description'] as String?,
        author: json['author'] as String?,
      );

  /// The record's key within the room. On `attributed` and `private` rooms this MUST be
  /// opaque — a random identifier, never a descriptive slug. A key reading
  /// `decision/acquire-northwind` defeats the encryption sitting beside it; structured
  /// naming belongs inside the sealed body.
  final String key;

  /// Server-assigned, monotonic per room.
  final int version;

  /// The epoch the record was sealed under. Absent on an `open` room.
  final int? epoch;

  /// Curation state. `retracted` is a tombstone: the body is gone, the key and version
  /// remain so incremental sync converges and the audit chain stays intact.
  final RecordMetadataStatus? status;
  final String updatedAt;

  /// Present only on an `open` room; sealed with the body otherwise.
  final String? title;

  /// Present only on an `open` room; sealed with the body otherwise.
  final String? description;

  /// The member who wrote it. Present on `open` and `attributed`; on `private` the
  /// author is inside the sealed body, where only members can read it.
  final String? author;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'key': key,
        'version': version,
        if (epoch != null) 'epoch': epoch!,
        if (status != null) 'status': status!.value,
        'updatedAt': updatedAt,
        if (title != null) 'title': title!,
        if (description != null) 'description': description!,
        if (author != null) 'author': author!,
      };
}

/// Curation state. `retracted` is a tombstone: the body is gone, the key and version
/// remain so incremental sync converges and the audit chain stays intact.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const RecordMetadataV2Status(String value) {
  static const RecordMetadataV2Status active = RecordMetadataV2Status('active');
  static const RecordMetadataV2Status deprecated =
      RecordMetadataV2Status('deprecated');
  static const RecordMetadataV2Status retracted =
      RecordMetadataV2Status('retracted');

  /// Every value this specification's schema permits.
  static const List<RecordMetadataV2Status> values = <RecordMetadataV2Status>[
    active,
    deprecated,
    retracted
  ];
}

/// What `rooms/records/list/0.2` returns: `RecordMetadata` plus `blobs`. A separate
/// definition, not a change to `RecordMetadata`, so that `rooms/records/list/0.1`
/// keeps the exact shape it published. Never the body.
class RecordMetadataV2 {
  const RecordMetadataV2({
    required this.key,
    required this.version,
    this.epoch,
    this.status,
    required this.updatedAt,
    this.title,
    this.description,
    this.author,
    this.blobs,
  });

  /// Read this payload from a decoded JSON object.
  factory RecordMetadataV2.fromJson(Map<String, dynamic> json) =>
      RecordMetadataV2(
        key: json['key'] as String,
        version: json['version'] as int,
        epoch: json['epoch'] as int?,
        status: json['status'] == null
            ? null
            : RecordMetadataV2Status(json['status'] as String),
        updatedAt: json['updatedAt'] as String,
        title: json['title'] as String?,
        description: json['description'] as String?,
        author: json['author'] as String?,
        blobs: json['blobs'] == null
            ? null
            : (json['blobs'] as List<dynamic>).map((e) => e as String).toList(),
      );

  /// The record's key within the room. On `attributed` and `private` rooms this MUST be
  /// opaque — a random identifier, never a descriptive slug. A key reading
  /// `decision/acquire-northwind` defeats the encryption sitting beside it; structured
  /// naming belongs inside the sealed body.
  final String key;

  /// Server-assigned, monotonic per room.
  final int version;

  /// The epoch the record was sealed under. Absent on an `open` room.
  final int? epoch;

  /// Curation state. `retracted` is a tombstone: the body is gone, the key and version
  /// remain so incremental sync converges and the audit chain stays intact.
  final RecordMetadataV2Status? status;
  final String updatedAt;

  /// Present only on an `open` room; sealed with the body otherwise.
  final String? title;

  /// Present only on an `open` room; sealed with the body otherwise.
  final String? description;

  /// The member who wrote it. Present on `open` and `attributed`; on `private` the
  /// author is inside the sealed body, where only members can read it.
  final String? author;

  /// The stored blobs this record names, as rooms/records/put/0.2 wrote them. Absent
  /// when it names none, when it is retracted, and on records written by put 0.1.
  /// Cleartext on every tier, as on the write, so a listing discloses which records
  /// carry files, never anything about the files beyond the blobs' sizes.
  final List<BlobRef>? blobs;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'key': key,
        'version': version,
        if (epoch != null) 'epoch': epoch!,
        if (status != null) 'status': status!.value,
        'updatedAt': updatedAt,
        if (title != null) 'title': title!,
        if (description != null) 'description': description!,
        if (author != null) 'author': author!,
        if (blobs != null) 'blobs': blobs!,
      };
}

/// Curation state. Committed rather than left out because a host that could flip
/// `active` to `retracted` would retract a record without touching a byte of it.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const CommittedRecordStatus(String value) {
  static const CommittedRecordStatus active = CommittedRecordStatus('active');
  static const CommittedRecordStatus deprecated =
      CommittedRecordStatus('deprecated');
  static const CommittedRecordStatus retracted =
      CommittedRecordStatus('retracted');

  /// Every value this specification's schema permits.
  static const List<CommittedRecordStatus> values = <CommittedRecordStatus>[
    active,
    deprecated,
    retracted
  ];
}

/// **The leaf preimage of the record tree** — the exact JSON object a host hashes into
/// a leaf, and the exact object a reader reassembles to check a `RecordTrace`. This
/// definition exists because a commitment nobody but its author can recompute is not a
/// commitment. `DataCommitment` names the tree; this names what goes into it, member
/// by member, so that a second implementation reaches the same root over the same
/// room. An earlier revision described the leaf as "this family's `RecordMetadata`
/// plus its stored content", which reads exact and is not: `RecordMetadata` is a
/// *projection* a listing returns — it renders `updatedAt` as a timestamp, promotes
/// `epoch` to the top level, carries `title` and `description` lifted out of an `open`
/// room's body, and has no `pinned` at all. A host hashing its own stored
/// representation and a reader hashing that projection commit to different roots, and
/// neither of them is wrong; there was simply no statement of which one counted. **It
/// is also the response payload of `rooms/records/get` with its verification members —
/// `dataCommitment`, `recordCount`, `headVersion` and `trace` — and `ext` removed.**
/// That is a design decision rather than a coincidence to be maintained by hand: the
/// reader of a single record already holds every member, so reassembling the preimage
/// is a *deletion* rather than a reconstruction, and no copy of the ciphertext is
/// carried twice — to be paid for on every read, and to disagree with itself. Members
/// are hashed in the order JCS (RFC 8785) puts them in, so nothing here depends on the
/// order they are written or served in. Nothing on the wire `$ref`s this definition,
/// so the generated libraries emit no type for it — deliberately. A consumer derives
/// the preimage from the response it already has (`Omit&lt;Response, "dataCommitment" |
/// "trace" | "ext"&gt;` and its equivalents), which cannot drift from that response the
/// way a second generated struct could. The definition is here to be *validated
/// against* and to be read. **Absence carries meaning, so every presence rule is
/// exact:** - `pinned` is present **only** when true. `"pinned": false` is not a
/// committed record: absent is how false is spelled here, and accepting both spellings
/// would give one record two roots. - `epoch` is **not** a member of this object. It
/// lives inside `sealed`, where the AEAD binds it; a top-level copy would be a second
/// place for it to disagree with itself. - `sealed` is present on `attributed` and
/// `private`, `cleartext` on `open`, and **neither** on a `retracted` tombstone, whose
/// body is gone. - `author` is present where the tier discloses one — `open` and
/// `attributed` — and absent on `private`, where the author is inside the sealed body.
/// - `title` and `description` are **not** members. A listing lifts them out of an
/// `open` room's body for display; committing to them *and* to the body they came from
/// would commit to the same bytes twice and leave a host free to choose which copy to
/// serve. A host that omits a member it holds, or serves one it does not, produces a
/// leaf the reader cannot reach, and the trace fails. Every way of getting this wrong
/// fails closed, which is what lets the rules be this strict.
class CommittedRecord {
  const CommittedRecord({
    required this.key,
    required this.version,
    required this.status,
    required this.updatedAt,
    this.pinned,
    this.author,
    this.sealed,
    this.cleartext,
  });

  /// Read this payload from a decoded JSON object.
  factory CommittedRecord.fromJson(Map<String, dynamic> json) =>
      CommittedRecord(
        key: json['key'] as String,
        version: json['version'] as int,
        status: CommittedRecordStatus(json['status'] as String),
        updatedAt: json['updatedAt'] as String,
        pinned: json['pinned'] as bool?,
        author: json['author'] as String?,
        sealed: json['sealed'] == null
            ? null
            : SealedRecord.fromJson(json['sealed'] as Map<String, dynamic>),
        cleartext: json['cleartext'] as Map<String, dynamic>?,
      );

  /// The record's key within the room. Also the sort key of the tree — see
  /// `DataCommitment` step 1.
  final String key;

  /// Server-assigned, monotonic per room.
  final int version;

  /// Curation state. Committed rather than left out because a host that could flip
  /// `active` to `retracted` would retract a record without touching a byte of it.
  final CommittedRecordStatus status;

  /// RFC 3339, as `RecordMetadata` renders it and as every other timestamp in this
  /// family is spelled. A host storing epoch seconds MUST render before hashing: the
  /// digest is over the wire form, not over the storage form.
  final String updatedAt;

  /// Present only when the record is pinned; absent means it is not. See the presence
  /// rules above — `false` is not a permitted spelling.
  final bool? pinned;

  /// The member who wrote it. Present on `open` and `attributed`; absent on `private`,
  /// where the author is sealed with the body. Committed because on an `attributed` room
  /// the author is part of what the record means.
  final String? author;

  /// The record as the host stores it on `attributed` and `private`. The **plaintext is
  /// never involved** in the commitment: the host holds ciphertext, and commits to
  /// exactly what it holds.
  final SealedRecord? sealed;

  /// The record body on an `open` room.
  final Map<String, dynamic>? cleartext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'key': key,
        'version': version,
        'status': status.value,
        'updatedAt': updatedAt,
        if (pinned != null) 'pinned': pinned!,
        if (author != null) 'author': author!,
        if (sealed != null) 'sealed': sealed!.toJson(),
        if (cleartext != null) 'cleartext': cleartext!,
      };
}

/// The root of the room's record tree — a host's commitment to *which records the room
/// holds*, as distinct from what any one of them says. A room's records are already
/// signed and room-bound, so a host cannot forge, alter or relocate one. What it can
/// do for free is stay silent: a listing that omits a record is indistinguishable from
/// a room that never held it. This value is what makes that omission detectable, so it
/// is only worth anything when the reader can compare it against a copy the host did
/// not choose for them — one it gave another member, one it gave the same member
/// earlier, or the witnessed anchor. A commitment read once, in isolation, proves
/// nothing. **A root on its own is not comparable, and an earlier revision of this
/// description said it was.** It claimed a host showing two members two different
/// roots had been caught, which is false while a room can move between two reads: the
/// host answers *there was a write*, and nothing contradicts it. Comparison needs the
/// state each root describes, which is what `HeadVersion` names — and `RecordCount` is
/// the other half of the same omission, since Certificate Transparency's signed tree
/// head is a root *and a size* and this family shipped only the root. A reader that
/// receives a `dataCommitment` **without** them can use it against a witnessed anchor,
/// where the epoch pins the state, and **MUST NOT** compare it against another root.
/// **The construction is normative**, because two hosts that compute different roots
/// over the same room make every comparison meaningless: 1. Take every record the room
/// holds — including tombstones, which are records — and order them by `key` using
/// unsigned byte order. 2. Leaf: `SHA-256(0x00 || JCS(record))`, where the record is a
/// `CommittedRecord` — that definition fixes the members exactly, and this step used
/// to name a *projection* instead, which two implementations could read two ways — JCS
/// is its RFC 8785 canonicalization, and `0x00` is RFC 6962's leaf-domain prefix. 3.
/// Internal node: `SHA-256(0x01 || left || right)`. 4. A level with an odd number of
/// nodes promotes the last one unchanged. It MUST NOT be duplicated: duplicating makes
/// a tree of n leaves collide with one of n+1 whose last is repeated, so two different
/// rooms commit to the same root. 5. A room holding no records commits to
/// `SHA-256("")`, a distinguished value rather than zeroes — a root of zeroes is what
/// an uninitialised buffer looks like, and an empty room is a real state a host must
/// be able to commit to honestly. The leaf covers the whole record rather than its
/// body, and that is deliberate: a host that could flip `status` from active to
/// retracted, move `pinned`, or rewrite `author` on an `attributed` room would rewrite
/// what the room means without touching a byte of ciphertext. The **plaintext is never
/// involved** — on the sealed tiers the host holds ciphertext and commits to exactly
/// what it stores. The commitment is over the **whole room**, never over the page
/// being returned. A page-scoped root is one a host satisfies by construction and
/// could never fail. Proving that a *particular* record sits under this root is a
/// separate question, answered by `RecordTrace` on a single-record read. A commitment
/// catches a host that equivocates; a trace binds one record to what the host
/// committed to. Neither is the other, and a reader wanting completeness needs both
/// plus a root it did not get from the host it is checking.
typedef DataCommitment = DigestMultibase;

/// How many records the room held when `DataCommitment` was computed — the number of
/// leaves in that tree, tombstones included, since a tombstone is a record. **Why a
/// root needs this.** Certificate Transparency's signed tree head is a root *and a
/// tree size*; this family shipped the root alone, and the half that was dropped is
/// the half that makes a listing checkable. A reader holding a **complete,
/// unfiltered** listing cannot recompute the root — a leaf commits to a whole record
/// and a listing returns a projection without the body — but it can count. A host that
/// omits a record from a listing while committing to a tree that holds it now
/// contradicts itself in the same response, with no second party and no anchor
/// involved. A host can of course understate both together. That is the point rather
/// than a hole: the omission stops being silence and becomes a **specific claim about
/// how many records the room holds**, which any other member's view, or any writer's
/// signed put acknowledgement, contradicts. Making an omission attributable is the
/// whole of what this machinery buys; it never claimed to make one impossible. **It
/// counts the room, never the page.** The same rule `DataCommitment` states, and the
/// same trap: a count scoped to what was returned is one a host satisfies by
/// construction. So this is only comparable against a listing read to the end with
/// **no** `prefix` and **no** `sinceVersion` — a filtered listing legitimately holds
/// fewer, and a reader that compares one against this has found a discrepancy it
/// created itself.
typedef RecordCount = int;

/// The highest version among the records `DataCommitment` covers. `0` for a room that
/// holds none. **Derived from the same set as the root, and not read from the room's
/// own counter.** The two agree for any host that has never erased a record — versions
/// are assigned strictly increasing and a retraction keeps its tombstone — but they
/// are not interchangeable, because a root and a counter are *two reads*, and two
/// reads are not a snapshot. A write landing between them yields a pair that is
/// individually correct and jointly false: two members holding roots taken over
/// different trees, labelled with one version. That reads as equivocation and is not,
/// and a **false accusation discredits the mechanism rather than the host** — the
/// worst outcome available here. Taken from the committed set, the version cannot
/// disagree with the root it labels, whatever else is happening to the room. The
/// corollary is worth stating: a host that **erases** a record — as distinct from
/// retracting it, which leaves a tombstone in the tree — moves the root without
/// necessarily moving this value, and two members straddling that erasure would see
/// one version over two roots. Erasure is a retention act with its own answer, and a
/// family that exposes one owes this definition another look. **This is what makes two
/// roots comparable at all**, and without it the comparison this family is built on
/// cannot be performed. A room moves: every put, curate and retraction assigns a new
/// version, so two roots taken at two moments differ legitimately and a reader learns
/// nothing from the difference. Shown two different roots, a host that equivocated and
/// a host that was merely written to are indistinguishable — the first can always
/// answer *the room moved between your reads*, and nothing contradicts it. A version
/// is assigned by exactly the mutations that change the tree — every put, curate and
/// retraction takes the next one — so the highest of them names the **state** the root
/// describes. Two roots carrying the same `headVersion` and differing is a host
/// caught: there is no write to attribute the difference to. Two roots carrying
/// different ones are simply two moments, and a reader should draw nothing from them.
/// A host can lie about this number too, and it is then lying about the counter it
/// also uses for optimistic concurrency (`expectedVersion`) and for incremental sync
/// (`sinceVersion`) — so a member holding a signed acknowledgement of a write at
/// version `V` contradicts any head below `V` directly. **Not a timestamp.** A time is
/// host-asserted, unverifiable and useless for this: two roots a second apart are not
/// evidence of anything, while two roots at one version are.
typedef HeadVersion = int;

/// What a room writes into its own witnessed log, so that a host serving a stale,
/// forked or partial view of it becomes **evident rather than merely possible**.
/// **Witnessed is the whole point.** Witnesses co-sign a `did:webvh` log entry, so a
/// value that rides one is singular: the room cannot have told two members two
/// different things about the same epoch without the log showing it. An anchor that
/// did not ride a log entry would be a value the host could equally have made up,
/// which is what every unanchored assertion in this family already is. It goes in a
/// **typed service entry** on the room's DID document, which is the only slot in a
/// `did:webvh` log entry that carries an ecosystem-defined value today: `parameters`
/// is a closed struct, `versionId` and `versionTime` are computed, and `proof` is the
/// witnesses' signature over the rest — it secures the anchor and cannot be it.
/// **Publishing one is not free.** A `did:webvh` update that supplies a document
/// rotates the DID's update key and refreshes its pre-rotation commitments, so every
/// anchor is a witnessed update *and* a rotation. That makes cadence an operational
/// decision rather than only a freshness one: a room anchoring on every write would
/// rotate its own DID's update key on every write.
class EpochAnchor {
  const EpochAnchor({
    required this.epoch,
    required this.epochAuthenticator,
    required this.headVersion,
    this.dataCommitment,
    this.recordCount,
  });

  /// Read this payload from a decoded JSON object.
  factory EpochAnchor.fromJson(Map<String, dynamic> json) => EpochAnchor(
        epoch: json['epoch'] as int,
        epochAuthenticator: json['epochAuthenticator'] as String,
        headVersion: json['headVersion'] as int,
        dataCommitment: json['dataCommitment'] as String?,
        recordCount: json['recordCount'] as int?,
      );

  /// The key epoch this anchor describes.
  final int epoch;

  /// The MLS epoch authenticator for `epoch` — a value every member of the group derives
  /// independently and no host can compute. A member whose own authenticator differs
  /// from the anchored one is in a **forked group**, which is the attack this exists to
  /// make visible.
  final DigestMultibase epochAuthenticator;

  /// The room's version watermark at the moment of anchoring, as the host reported it.
  final HeadVersion headVersion;

  /// The room's record-tree root at the same moment. OPTIONAL for the same reason it is
  /// on a read: a host that maintains no tree asserts none, and an owner cannot anchor
  /// what it was not given. Where it is present it is the only comparison in this family
  /// that needs neither a gossip channel rooms deliberately lack nor durable state in a
  /// member's agent — every member reads the same anchored root.
  final DataCommitment? dataCommitment;

  /// How many records the room held. Present with `dataCommitment` and absent without
  /// it: a root without the state it describes is not comparable to another root.
  final RecordCount? recordCount;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'epoch': epoch,
        'epochAuthenticator': epochAuthenticator,
        'headVersion': headVersion,
        if (dataCommitment != null) 'dataCommitment': dataCommitment!,
        if (recordCount != null) 'recordCount': recordCount!,
      };
}

/// How often this room intends to write an `EpochAnchor`. **A statement of intent, not
/// a schedule anything enforces** — nothing in this family can make an owner anchor.
/// It is worth stating anyway, and the reason is the interesting part: it makes
/// **silence legible**. A room that says `renewal` and has not anchored in ten epochs
/// is telling a member something, and a member who did not know what to expect could
/// not have noticed. A room that says `never` is telling them not to wait for one. -
/// `never` — no anchor is intended. Honest, and cheap: anchoring costs a witnessed
/// update and a rotation of the room DID's update key each time. - `renewal` — one
/// anchor per epoch change, which is the cadence §9's lifecycle already moves at. -
/// `manual` — the owner anchors when they decide to. A member should draw no freshness
/// expectation from this at all, which is exactly what it is for: it is the honest
/// answer where there is no rule. Deliberately not a duration. A room that promised
/// "daily" would be making a claim its owner's availability cannot keep, and a member
/// comparing against a clock would read an owner's holiday as a host's misbehaviour.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const AnchorCadence(String value) {
  static const AnchorCadence never = AnchorCadence('never');
  static const AnchorCadence renewal = AnchorCadence('renewal');
  static const AnchorCadence manual = AnchorCadence('manual');

  /// Every value this specification's schema permits.
  static const List<AnchorCadence> values = <AnchorCadence>[
    never,
    renewal,
    manual
  ];
}

/// RecordTraceItem, generated from its schema.
class RecordTraceItem {
  const RecordTraceItem({
    required this.sibling,
    required this.siblingIsLeft,
  });

  /// Read this payload from a decoded JSON object.
  factory RecordTraceItem.fromJson(Map<String, dynamic> json) =>
      RecordTraceItem(
        sibling: json['sibling'] as String,
        siblingIsLeft: json['siblingIsLeft'] as bool,
      );

  /// The sibling node's hash — a leaf hash or an internal node hash of this room's
  /// record tree, encoded exactly as `DataCommitment` is. A digest over **bytes**,
  /// produced by one of the two prefixed constructions in `DataCommitment`, not over a
  /// JSON document.
  final DigestMultibase sibling;

  /// Whether the sibling is the **left** child of the parent; the node being proved is
  /// the other one. Concatenation order is the whole of what a Merkle proof asserts, so
  /// this bit is load-bearing — inverting it on a single step yields a different root,
  /// and a reader that infers it from the record's position has assumed a tree shape the
  /// host never stated.
  final bool siblingIsLeft;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'sibling': sibling,
        'siblingIsLeft': siblingIsLeft,
      };
}

/// The path from one record's leaf to the room's `DataCommitment` — a Merkle inclusion
/// proof, in the vocabulary this work already uses for it. **It is not called
/// `proof`** because in this framework that word is taken: `proof` is the document's
/// data-integrity proof (SPEC §7.3), and a payload member of the same name in the same
/// document invites reading one for the other. The two are not interchangeable and the
/// confusion would be silent. **To verify**, given the `CommittedRecord` reassembled
/// from the same response: 1. `h = SHA-256(0x00 || JCS(record))` — the leaf, by
/// `DataCommitment` step 2. 2. For each step in order: `h = SHA-256(0x01 || sibling ||
/// h)` when `siblingIsLeft` is true, and `SHA-256(0x01 || h || sibling)` when it is
/// false. 3. `h` **MUST** equal the `dataCommitment` **carried in the same response**.
/// Not one from an earlier read, and not one from a listing: a room moves, and a trace
/// is only ever a statement about the tree it was cut from. A host **MUST** compute
/// the trace and the commitment from the same snapshot. An **empty array is valid**
/// and is not the same as an absent member. It says the room holds exactly one record,
/// whose leaf is the root; absence of `trace` says the host offered no trace at all. A
/// trace is **not** always `ceil(log2 n)` steps. A level that promotes an odd node
/// unchanged (`DataCommitment` step 4) contributes no step for that node, so a reader
/// must follow the steps it was given rather than count them against a tree size it
/// assumed. `maxItems` bounds a tree of 2⁶⁴ records. Verification cost is the reader's
/// and the array is the host's, so the ceiling is stated rather than left to whoever
/// writes the loop. **What a trace does not prove.** It binds a record to a root. It
/// says nothing about whether that root is the room's — only comparing the root
/// against one the host did not choose does that, exactly as `DataCommitment`
/// describes. A reader that verifies a trace against a root received in the same
/// breath has checked the host's arithmetic and nothing else. The two mechanisms
/// answer different questions and neither substitutes for the other.
typedef RecordTrace = List<RecordTraceItem>;

/// Whether the record's `RecordTrace` reached the `dataCommitment` served beside it.
/// `verified` says the record is under the root the host asserted — and **nothing
/// about whether that root is the room's**, which is what `priorRoots` and an anchor
/// are for. `notOffered` is a host that maintains no tree, which is legal and
/// informative. `failed` is arithmetic that does not close: the host served a path
/// that does not reach its own root, which is either a defect or a fabrication and is
/// not distinguishable from here.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const ReadVerificationTrace(String value) {
  static const ReadVerificationTrace verified =
      ReadVerificationTrace('verified');
  static const ReadVerificationTrace failed = ReadVerificationTrace('failed');
  static const ReadVerificationTrace notOffered =
      ReadVerificationTrace('notOffered');

  /// Every value this specification's schema permits.
  static const List<ReadVerificationTrace> values = <ReadVerificationTrace>[
    verified,
    failed,
    notOffered
  ];
}

/// Whether this root matches what the agent has seen from this host for this room **at
/// this `headVersion`**. This is the comparison a member cannot make for themselves. A
/// tab does not outlive itself and a CLI holds nothing; the agent is the only party on
/// the member's side of the boundary that saw both reads. - `agree` — seen at this
/// head before, same root. - `conflict` — seen at this head before, **different
/// root**. A host caught: there is no write to attribute the difference to, because a
/// write would have moved the head. - `noneHeld` — first read at this head. Not
/// evidence of anything; a memory of one is not a comparison. - `notChecked` — this
/// agent keeps no root history. An honest answer for an agent that cannot make the
/// comparison, and **not** a synonym for `noneHeld`: one says nothing was found, the
/// other says nothing was looked for. REQUIRED, so that an agent which does not check
/// has to say so rather than omit the question.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const ReadVerificationPriorRoots(String value) {
  static const ReadVerificationPriorRoots agree =
      ReadVerificationPriorRoots('agree');
  static const ReadVerificationPriorRoots conflict =
      ReadVerificationPriorRoots('conflict');
  static const ReadVerificationPriorRoots noneHeld =
      ReadVerificationPriorRoots('noneHeld');
  static const ReadVerificationPriorRoots notChecked =
      ReadVerificationPriorRoots('notChecked');

  /// Every value this specification's schema permits.
  static const List<ReadVerificationPriorRoots> values =
      <ReadVerificationPriorRoots>[agree, conflict, noneHeld, notChecked];
}

/// How what the host served compares with the room's own **witnessed anchor**
/// (`EpochAnchor`). This is the comparison that needs neither a gossip channel rooms
/// deliberately lack nor durable state in an agent: every member resolves the same
/// room DID and reads the same entry, co-signed by witnesses. It is the only one of
/// the three a first-time reader can make. - `agrees` — the host served the anchored
/// state, and its root matches. - `ahead` — the room has moved past the anchor. The
/// ordinary case; an anchor describes a moment, not the present, and says nothing
/// about records written since. - `behind` — **the host is serving a state older than
/// the room's own witnessed statement.** A rollback, and a detection nothing else in
/// this family can make: a member with no history, no peer and no prior read still
/// catches it. - `conflict` — same `headVersion` as the anchor, different root. The
/// host has contradicted a value its own room published and witnesses co-signed. -
/// `none` — the room has published no anchor. Not a fault; anchoring costs a witnessed
/// update and a key rotation, and a room may reasonably decline. - `notChecked` — the
/// consumer did not resolve the room. An honest answer, and **not** a synonym for
/// `none`: one says the room published nothing, the other says nobody looked.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const ReadVerificationAnchor(String value) {
  static const ReadVerificationAnchor agrees = ReadVerificationAnchor('agrees');
  static const ReadVerificationAnchor ahead = ReadVerificationAnchor('ahead');
  static const ReadVerificationAnchor behind = ReadVerificationAnchor('behind');
  static const ReadVerificationAnchor conflict =
      ReadVerificationAnchor('conflict');
  static const ReadVerificationAnchor none = ReadVerificationAnchor('none');
  static const ReadVerificationAnchor notChecked =
      ReadVerificationAnchor('notChecked');

  /// Every value this specification's schema permits.
  static const List<ReadVerificationAnchor> values = <ReadVerificationAnchor>[
    agrees,
    ahead,
    behind,
    conflict,
    none,
    notChecked
  ];
}

/// Whether the number of records returned matches the `recordCount` the host committed
/// to. Only ever comparable against a listing with **no** `prefix`, **no**
/// `sinceVersion` and read to its end — anything else legitimately holds fewer, and
/// comparing it is a discrepancy the reader manufactured. `notComparable` is that
/// case, and it is the common one. `short` is a host contradicting itself inside one
/// exchange: it committed to a tree of N records and served fewer, with no filter to
/// explain the difference. That is the omission the commitment exists to make
/// detectable, caught without a second party and without an anchor.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const ReadVerificationCount(String value) {
  static const ReadVerificationCount agrees = ReadVerificationCount('agrees');
  static const ReadVerificationCount short = ReadVerificationCount('short');
  static const ReadVerificationCount notComparable =
      ReadVerificationCount('notComparable');
  static const ReadVerificationCount notOffered =
      ReadVerificationCount('notOffered');

  /// Every value this specification's schema permits.
  static const List<ReadVerificationCount> values = <ReadVerificationCount>[
    agrees,
    short,
    notComparable,
    notOffered
  ];
}

/// What the host asserted about the room, passed through unaltered so the member can
/// compare it somewhere this agent cannot reach — with another member, or against a
/// witnessed anchor. All three or none: a root without the state it describes is not
/// comparable to another root, which is the whole of `HeadVersion`.
class ReadVerificationHead {
  const ReadVerificationHead({
    required this.dataCommitment,
    required this.recordCount,
    required this.headVersion,
  });

  /// Read this payload from a decoded JSON object.
  factory ReadVerificationHead.fromJson(Map<String, dynamic> json) =>
      ReadVerificationHead(
        dataCommitment: json['dataCommitment'] as String,
        recordCount: json['recordCount'] as int,
        headVersion: json['headVersion'] as int,
      );

  final DataCommitment dataCommitment;
  final RecordCount recordCount;
  final HeadVersion headVersion;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'dataCommitment': dataCommitment,
        'recordCount': recordCount,
        'headVersion': headVersion,
      };
}

/// What the agent checked on the member's behalf, and what it found. **A verdict,
/// never an error.** None of these values fails the task, including the ones that
/// report a host caught out. A member's own agent refusing to hand over a record
/// because the *host* misbehaved punishes the member for somebody else's act — and
/// locks them out of the room holding the records that would show what happened, at
/// the moment they most need them. The consequence belongs on the **write** path,
/// where continuing to hand material to a party you have caught is what compounds the
/// damage. So a consumer **MUST NOT** treat any value here as a failed read, and
/// **MUST** surface an adverse one rather than logging it. What that costs is words: a
/// member shown a bare warning icon dismisses it, and a member later refused a write
/// with no explanation blames their own agent. A detection the member attributes to
/// the wrong party is worse than no detection. Members are **absent where the task
/// cannot produce them** rather than carrying a not-applicable value — a listing has
/// no `trace` because there is no single record to trace, and a single read has no
/// `count` because a count is only checkable against a listing read to its end.
class ReadVerification {
  const ReadVerification({
    this.trace,
    required this.priorRoots,
    this.anchor,
    this.count,
    this.head,
  });

  /// Read this payload from a decoded JSON object.
  factory ReadVerification.fromJson(Map<String, dynamic> json) =>
      ReadVerification(
        trace: json['trace'] == null
            ? null
            : ReadVerificationTrace(json['trace'] as String),
        priorRoots: ReadVerificationPriorRoots(json['priorRoots'] as String),
        anchor: json['anchor'] == null
            ? null
            : ReadVerificationAnchor(json['anchor'] as String),
        count: json['count'] == null
            ? null
            : ReadVerificationCount(json['count'] as String),
        head: json['head'] == null
            ? null
            : ReadVerificationHead.fromJson(
                json['head'] as Map<String, dynamic>),
      );

  /// Whether the record's `RecordTrace` reached the `dataCommitment` served beside it.
  /// `verified` says the record is under the root the host asserted — and **nothing
  /// about whether that root is the room's**, which is what `priorRoots` and an anchor
  /// are for. `notOffered` is a host that maintains no tree, which is legal and
  /// informative. `failed` is arithmetic that does not close: the host served a path
  /// that does not reach its own root, which is either a defect or a fabrication and is
  /// not distinguishable from here.
  final ReadVerificationTrace? trace;

  /// Whether this root matches what the agent has seen from this host for this room **at
  /// this `headVersion`**. This is the comparison a member cannot make for themselves. A
  /// tab does not outlive itself and a CLI holds nothing; the agent is the only party on
  /// the member's side of the boundary that saw both reads. - `agree` — seen at this
  /// head before, same root. - `conflict` — seen at this head before, **different
  /// root**. A host caught: there is no write to attribute the difference to, because a
  /// write would have moved the head. - `noneHeld` — first read at this head. Not
  /// evidence of anything; a memory of one is not a comparison. - `notChecked` — this
  /// agent keeps no root history. An honest answer for an agent that cannot make the
  /// comparison, and **not** a synonym for `noneHeld`: one says nothing was found, the
  /// other says nothing was looked for. REQUIRED, so that an agent which does not check
  /// has to say so rather than omit the question.
  final ReadVerificationPriorRoots priorRoots;

  /// How what the host served compares with the room's own **witnessed anchor**
  /// (`EpochAnchor`). This is the comparison that needs neither a gossip channel rooms
  /// deliberately lack nor durable state in an agent: every member resolves the same
  /// room DID and reads the same entry, co-signed by witnesses. It is the only one of
  /// the three a first-time reader can make. - `agrees` — the host served the anchored
  /// state, and its root matches. - `ahead` — the room has moved past the anchor. The
  /// ordinary case; an anchor describes a moment, not the present, and says nothing
  /// about records written since. - `behind` — **the host is serving a state older than
  /// the room's own witnessed statement.** A rollback, and a detection nothing else in
  /// this family can make: a member with no history, no peer and no prior read still
  /// catches it. - `conflict` — same `headVersion` as the anchor, different root. The
  /// host has contradicted a value its own room published and witnesses co-signed. -
  /// `none` — the room has published no anchor. Not a fault; anchoring costs a witnessed
  /// update and a key rotation, and a room may reasonably decline. - `notChecked` — the
  /// consumer did not resolve the room. An honest answer, and **not** a synonym for
  /// `none`: one says the room published nothing, the other says nobody looked.
  final ReadVerificationAnchor? anchor;

  /// Whether the number of records returned matches the `recordCount` the host committed
  /// to. Only ever comparable against a listing with **no** `prefix`, **no**
  /// `sinceVersion` and read to its end — anything else legitimately holds fewer, and
  /// comparing it is a discrepancy the reader manufactured. `notComparable` is that
  /// case, and it is the common one. `short` is a host contradicting itself inside one
  /// exchange: it committed to a tree of N records and served fewer, with no filter to
  /// explain the difference. That is the omission the commitment exists to make
  /// detectable, caught without a second party and without an anchor.
  final ReadVerificationCount? count;

  /// What the host asserted about the room, passed through unaltered so the member can
  /// compare it somewhere this agent cannot reach — with another member, or against a
  /// witnessed anchor. All three or none: a root without the state it describes is not
  /// comparable to another root, which is the whole of `HeadVersion`.
  final ReadVerificationHead? head;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (trace != null) 'trace': trace!.value,
        'priorRoots': priorRoots.value,
        if (anchor != null) 'anchor': anchor!.value,
        if (count != null) 'count': count!.value,
        if (head != null) 'head': head!.toJson(),
      };
}

/// Withdraws one credential — a membership credential or any authority link — by its
/// `id`.
class CredentialRevocation {
  const CredentialRevocation({
    required this.kind,
    required this.credentialId,
    required this.revokedAt,
    this.until,
  });

  /// Read this payload from a decoded JSON object.
  factory CredentialRevocation.fromJson(Map<String, dynamic> json) =>
      CredentialRevocation(
        kind: json['kind'],
        credentialId: json['credentialId'] as String,
        revokedAt: json['revokedAt'] as String,
        until: json['until'] as String?,
      );

  final Object? kind;

  /// The `id` of the credential withdrawn, as `rooms/owner/issue-authority` and
  /// `rooms/owner/issue-membership` return it, or as an attenuated credential carries
  /// it.
  final String credentialId;

  /// When the room made this withdrawal.
  final String revokedAt;

  /// OPTIONAL. After this instant every credential the entry matches has expired anyway,
  /// so a host MAY discard the entry and the room MAY omit it from later lists. Absent
  /// means the entry is kept for as long as the room keeps a list.
  final String? until;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'kind': kind,
        'credentialId': credentialId,
        'revokedAt': revokedAt,
        if (until != null) 'until': until!,
      };
}

/// Withdraws a party: every credential naming them as subject or issuer whose
